public class TurnstileGateTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        try {
            TurnstileGate gate = new TurnstileGate();
            check("no tickets yet", 0, gate.ticketCount());

            gate.addTicket("A1");
            gate.addTicket("B2");
            gate.addTicket("A1");
            check("duplicate code stored once", 2, gate.ticketCount());

            gate.addTicket(null);
            gate.addTicket("");
            check("null and empty codes ignored", 2, gate.ticketCount());

            check("scan a loaded code", true, gate.scan("A1"));
            check("scan an unknown code", false, gate.scan("ZZ"));
            check("scan null", false, gate.scan(null));
            check("admitted counts only successes", 1, gate.getAdmitted());

            check("same code scans again", true, gate.scan("A1"));
            check("admitted after second success", 2, gate.getAdmitted());

            TicketReader direct = new TicketReader();
            direct.load("C3");
            check("the test is in the same package, so it may call accepts", true, direct.accepts("C3"));
        } catch (RuntimeException e) {
            System.out.println("FAIL  unexpected exception -- expected none but got " + e);
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

