import java.util.HashSet;
import java.util.Set;

/**
 * Provided -- do not edit.
 *
 * TicketReader has no access modifier on the class or on load/accepts/size, so
 * they are PACKAGE-PRIVATE: only code in the same package (this file, and the
 * test) may touch them. The world outside the package cannot.
 */
class TicketReader {

    private final Set<String> valid = new HashSet<>();

    void load(String code) {
        if (code != null && !code.isEmpty()) {
            valid.add(code);
        }
    }

    boolean accepts(String code) {
        return code != null && valid.contains(code);
    }

    int size() {
        return valid.size();
    }
}

public class TurnstileGate {

    private final TicketReader reader = new TicketReader();
    private int admitted = 0;

    public void addTicket(String code) {
        reader.load(code);
    }

    public boolean scan(String code) {
        if (!reader.accepts(code)) {
            return false;
        }
        admitted++;
        return true;
    }

    public int getAdmitted() {
        return admitted;
    }

    public int ticketCount() {
        return reader.size();
    }
}
